class Pet:
    def __init__(self,name):
        self.name = name
        self.energy = 5
    def feed(self,amount=1):
        if amount > 0:
            self.energy = min(10,self.energy + amount)
    def play(self):
        if self.energy < 2:
            return False
        self.energy -= 2
        return True
    def __repr__(self):
        return f"Pet({self.name}, energy={self.energy})"
